// Host component/UI diagnostics. These are not final APK or Android passes.
#include "engine.h"
#include "matheditor.h"
#include "argumentguide.h"
#include <QtWidgets>
#include <iostream>
#include <memory>

int main(int argc,char **argv){
    QApplication app(argc,argv);QThread worker;QObject owner;owner.moveToThread(&worker);worker.start();
    std::unique_ptr<CalcEngine> engine;QVector<FunctionMetadata> metadata;
    QMetaObject::invokeMethod(&owner,[&]{engine=std::make_unique<CalcEngine>();metadata=engine->functionMetadata();},Qt::BlockingQueuedConnection);
    auto evaluate=[&](const QString &expression){CalcResult result;QMetaObject::invokeMethod(&owner,[&]{result=engine->evaluate(expression);},Qt::BlockingQueuedConnection);return result;};
    int failures=0,checks=0;auto check=[&](bool okay,const QString &label){++checks;if(!okay)++failures;std::cout<<(okay?"PASS ":"FAIL ")<<label.toStdString()<<'\n';};
    auto lookup=[&](const QString &name){for(const auto &value:metadata)if(value.name==name||value.aliases.contains(name))return value;return FunctionMetadata();};
    MathEditor earlyEditor;MathEditor::setDefaultFunctionMetadata(metadata);
    earlyEditor.insertTemplate("taxadd(");check(earlyEditor.text().count(QChar(0x25a1))==2,"default snapshot refresh updates already-created editors");
    MathEditor lazyEditor;lazyEditor.insertTemplate("atan2(");check(lazyEditor.text().count(QChar(0x25a1))==2,"lazy-created editor inherits immutable current metadata");
    MathEditor editor;editor.setFunctionMetadata(metadata);editor.resize(360,180);editor.show();editor.setFocus();
    auto templateFor=[&](QString name){editor.clear();editor.insertTemplate(name+"(");return editor.text().count(QChar(0x25a1));};
    const QMap<QString,int> minimums{{"taxadd",2},{"taxremove",2},{"taxpart",2},{"brackettax",2},{"grossup",2},{"grossupbrackets",2},{"markup",2},{"margin",2},{"pricefrommarkup",2},{"pricefrommargin",2},{"allocate",2},{"runway",2},{"npv",2},{"npv0",2},{"xirr",2},{"realreturn",2},{"loanpayment",3},{"breakeven",3},{"prorate",3},{"xnpv",3},{"datejd",3},{"cagr",3},{"inflationadjust",3},{"targetsales",4},{"fxnet",5},{"atan2",2},{"irr",1},{"linearfit",1},{"quadraticfit",1},{"cubicfit",1}};
    for(auto it=minimums.cbegin();it!=minimums.cend();++it){const int count=templateFor(it.key());check(count==it.value(),it.key()+" required rectangle count "+QString::number(count));check(editor.argumentContext().metadata.complete&&editor.argumentContext().ranges.size()==it.value(),it.key()+" carries complete argument guidance");}
    const QStringList stats{"number","total","min","max","range","median","mode","percentile","quartile","decile","iqr","mean","geomean","harmmean","rms","weighmean","trimmean","winsormean","var","varp","stdev","stdevp","stderr","meandev","poolvar","cov","pearson","spearman","linearfit","quadraticfit","cubicfit"};
    for(const auto &name:stats){auto value=lookup(name);check(value.complete&&templateFor(name)==value.minimumArguments,name+" STAT alias uses actual contract");}
    auto fill=[&](const QString &name,const QStringList &values){templateFor(name);for(int i=0;i<values.size();++i){if(i)editor.focusArgument(i);editor.insert(values[i]);}return editor.canonicalText();};
    struct Case{QString name;QStringList values;QString expected;};
    const QVector<Case> cases{{"taxadd",{"100","0.27"},"127"},{"atan2",{"0","1"},"0"},{"loanpayment",{"1200","0","12"},"100"},{"mean",{"[1,2,3]"},"2"},{"npv",{"0.1","[110,121]"},"200"},{"npv0",{"0.1","[-100,110]"},"0"},{"brackettax",{"1500","[0,0.1;1000,0.2]"},"200"},{"fxnet",{"100","400","0.01","1","100"},"39104"}};
    for(const auto &test:cases){const QString source=fill(test.name,test.values);auto result=evaluate(source);check(!source.isEmpty()&&result.ok&&result.serialized==test.expected,test.name+" offered fields evaluate to independent expected "+test.expected+" actual "+result.serialized);check(editor.functionArgumentHelp().contains(test.name)&&!editor.argumentContext().ranges.isEmpty(),test.name+" help persists after all fields filled");}
    fill("irr",{"[-100,110]"});auto irr=evaluate(editor.canonicalText());const double irrNumber=evaluate("abs(("+irr.serialized+")-0.1)<1e-10").serialized.toDouble();check(irr.ok&&irrNumber==1,"IRR vector-only returns 0.1 within 1e-10");
    fill("loanpayment",{"1200","0.01","12"});const auto endPayment=evaluate(editor.canonicalText());check(editor.addFunctionArgument()&&editor.text().endsWith(QString::fromUtf8(",□)")),"optional payment timing added explicitly");editor.insert("1");auto beginPayment=evaluate(editor.canonicalText());auto relation=evaluate("abs(("+endPayment.serialized+")/1.01-("+beginPayment.serialized+"))<1e-10");check(beginPayment.ok&&relation.serialized=="1","optional beginning payment changes answer by known 1.01 factor");check(!editor.addFunctionArgument(),"finite maximum prevents excess optional arguments");check(editor.removeLastFunctionArgument()&&editor.text()=="loanpayment(1200,0.01,12)","remove optional argument retains required values");check(!editor.removeLastFunctionArgument(),"required arguments cannot be removed by optional control");editor.undo();check(editor.text()=="loanpayment(1200,0.01,12,1)","undo restores removed optional value");editor.redo();check(editor.text()=="loanpayment(1200,0.01,12)","redo removes exactly optional value");
    fill("xirr",{"[-100,110]","[datejd(2024,1,1),datejd(2025,1,1)]"});check(editor.addFunctionArgument(4)&&editor.text().endsWith(QString::fromUtf8(",0,-0.9999,□)")),"choosing later optional max inserts exact basis and minimum defaults");editor.insert("1");check(evaluate(editor.canonicalText()).ok,"later explicit optional argument preserves positional semantics");
    FunctionMetadata variadic;for(const auto &value:metadata)if(value.complete&&value.maximumArguments<0&&value.minimumArguments>0&&value.minimumArguments<=8){variadic=value;break;}
    templateFor(variadic.name);const int min=variadic.minimumArguments;check(variadic.complete&&editor.addFunctionArgument()&&editor.argumentContext().ranges.size()==min+1,"variadic "+variadic.name+" next argument supported");check(editor.removeLastFunctionArgument()&&editor.argumentContext().ranges.size()==min,"variadic added argument removable down to minimum");
    editor.setText("10+taxadd(mean([1,2,3]),0.27)+5");editor.setCursorPosition(editor.text().indexOf("2"));auto inner=editor.argumentContext();check(inner.functionName=="mean"&&inner.ranges.size()==1,"vector commas do not split nested mean argument");editor.setCursorPosition(editor.text().indexOf("0.27"));auto outer=editor.argumentContext();check(outer.functionName=="taxadd"&&outer.argumentIndex==1&&outer.ranges.size()==2,"caret tracks enclosing tax rate after nested call");editor.focusArgument(0);check(editor.selectedText()=="mean([1,2,3])","direct argument selection preserves entire nested subtree");editor.insertTemplate("taxremove(");check(editor.text()==QString::fromUtf8("10+taxadd(taxremove(mean([1,2,3]),□),0.27)+5"),"nested selected insertion preserves outer adjacent values");editor.insert("0.1");editor.undo();check(editor.text().contains(QChar(0x25a1)),"nested argument correction undo retains slot");editor.redo();check(editor.text()=="10+taxadd(taxremove(mean([1,2,3]),0.1),0.27)+5","nested correction redo restores exact expression");
    editor.setText("f(\"x,y\",[1,2;3,4],g(4,5))");editor.setCursorPosition(3);check(editor.argumentContext().ranges.size()==3,"quoted/vector/matrix/nested separators ignored by outer argument scanner");
    editor.setText("taxadd(100,0.27)");editor.setCursorPosition(7);check(editor.focusNextArgument()&&editor.selectedText()=="0.27","next argument visits filled value");check(editor.focusNextArgument(true)&&editor.selectedText()=="100","previous argument returns to filled value");editor.end();check(!editor.argumentContext().active(),"outside call caret exits argument guide");editor.setCursorPosition(7);check(editor.argumentContext().argumentIndex==0,"re-entry restores named context");
    editor.clear();editor.insertTemplate("unregistered_test_function(");check(editor.text()=="unregistered_test_function()"&&editor.slotRects().isEmpty()&&!editor.argumentContext().metadata.complete,"unknown metadata never guesses one rectangle");check(editor.functionArgumentHelp().contains("unavailable"),"unknown metadata fallback is explicit");
    editor.clear();editor.insertTemplate("rand(");check(lookup("rand").minimumArguments==0&&editor.text()=="rand()"&&editor.slotRects().isEmpty()&&editor.isComplete(),"zero-required function has no compulsory blank");
    editor.setStructuredInput(false);check(templateFor("taxadd")==2,"linear entry uses identical required argument count");editor.setStructuredInput(true);
    auto *guide=new ArgumentGuide(&editor);guide->resize(320,guide->heightForWidth(320));guide->show();fill("taxadd",{"100","0.27"});app.processEvents();check(guide->findChild<QPushButton*>("functionArgumentHelp")->accessibleName().contains("Tax rate"),"touch guidance exposes meaningful accessible current argument after filling");
    bool dialogShown=false,requiredProtected=false;
    QTimer::singleShot(20,[&]{auto *dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget());if(!dialog)return;dialogShown=dialog->objectName()=="functionArgumentDialog";auto *remove=dialog->findChild<QPushButton*>("functionRemoveArgument");requiredProtected=remove&&!remove->isEnabled();dialog->reject();});guide->findChild<QPushButton*>("functionArgumentHelp")->click();check(dialogShown&&requiredProtected,"native touch help opens and protects required arguments");delete guide;
    editor.setText("taxadd(100,0.27)");
    auto *accessible=QAccessible::queryAccessibleInterface(&editor);auto *textInterface=accessible?accessible->textInterface():nullptr;auto *editInterface=accessible?accessible->editableTextInterface():nullptr;
    check(textInterface&&editInterface,"custom editor exposes native accessible text and editable-text interfaces");
    if(textInterface&&editInterface){textInterface->setSelection(0,7,10);int first=-1,last=-1;textInterface->selection(0,&first,&last);check(first==7&&last==10&&textInterface->text(first,last)=="100","accessible selection uses canonical source positions");editInterface->replaceText(7,10,"200");check(editor.text()=="taxadd(200,0.27)","accessible editing replaces only selected argument");check(!textInterface->characterRect(7).isEmpty(),"accessible characters expose screen geometry");}
    MathEditor large;large.resize(160,90);QFont largeFont=large.font();largeFont.setPixelSize(36);large.setFont(largeFont);large.setReadOnly(true);large.setResultPresentation(true);large.setProperty("androidPreserveMathScale",true);large.setText(QString(80,'9'));large.show();app.processEvents();
    check(large.naturalSize().width()>160&&large.sourceCharacterRect(0).height()>30,"large math typography remains readable rather than fitting entire long value");
    const auto initial=large.sourceCharacterRect(0);QWheelEvent scroll(QPointF(80,40),QPointF(80,40),QPoint(),QPoint(0,-120),Qt::NoButton,Qt::NoModifier,Qt::NoScrollPhase,false);QApplication::sendEvent(&large,&scroll);check(large.sourceCharacterRect(0).x()<initial.x()&&large.text()==QString(80,'9'),"overflowing result scrolls locally without changing complete source");
    large.setReadOnly(false);large.end();check(large.cursorRect().right()<=large.width()&&large.cursorRect().left()>=0,"caret remains reachable at end of large horizontally scrolled input");
    QMetaObject::invokeMethod(&owner,[&]{engine.reset();},Qt::BlockingQueuedConnection);worker.quit();worker.wait();
    std::cout<<checks<<" checks, "<<failures<<" failures\n";return failures?1:0;
}
